import{_ as o,a0 as p,w as u,s as r,ao as x,I as a,x as e,a1 as s,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"2014年会是  Linux桌面年 吗？ | LCTT x X-CMD","titleTemplate":false,"description":"2014年会是  Linux桌面年 吗？ | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"2014年会是  Linux桌面年 吗？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"2014年会是  Linux桌面年 吗？ | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141211 Was 2014 The Year of Linux Desktop","title":"2014年会是  Linux桌面年 吗？","tag":"201412","desc":""},"relativePath":"201412/20141211 Was 2014 The Year of Linux Desktop.md","filePath":"[post].md"}'),l={name:"201412/20141211 Was 2014 The Year of Linux Desktop.md"};function L(m,t,f,d,T,g){const i=p("Link");return u(),r("div",null,[t[13]||(t[13]=x('<h1 id="_2014年会是-linux桌面年-吗" tabindex="-1">2014年会是 &quot;Linux桌面年&quot;吗？ <a class="header-anchor" href="#_2014年会是-linux桌面年-吗" aria-label="Permalink to “2014年会是 Linux桌面年吗？”">​</a></h1><blockquote><p>Linux桌面现在终于发出最强音！</p></blockquote><p><img src="http://i1-news.softpedia-static.com/images/news2/Was-2014-The-Year-of-Linux-Desktop-467036-2.jpg" alt=""></p><p><strong>看来Linux在2014年有很多改变，许多用户都表示今年Linux的确有进步，但是仅凭这个就能断定2014年就是&quot;Linux桌面年&quot;吗？</strong></p><p>&quot;Linux桌面年&quot;这句话，在过去几年就被传诵得像句颂歌一样，可以说是在试图用一种比较有意义的方式来标记它的发展进程。此类事情目前还没有发生过，在我们的见证下也从无先例，所以这就不难理解为什么Linux用户会用这个角度去看待这句话。</p><p>大多数软件和硬件领域不太会有这种快速的进步，都以较慢的速度发展，但是对于那些在工业领域有更好眼光的人来说，事情就会变得疯狂。即使有可能，针对某一时刻或某一事件还是比较困难的，但是Linux在几年的过程中还是以指数方式迅速发展成长。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Was-2014-The-Year-of-Linux-Desktop-467036-3.jpg" alt=""></p><h3 id="linux桌面年这句话不可轻言" tabindex="-1">Linux桌面年这句话不可轻言 <a class="header-anchor" href="#linux桌面年这句话不可轻言" aria-label="Permalink to “Linux桌面年这句话不可轻言”">​</a></h3><p>没有一个比较权威的人和机构能判定Linux桌面年已经到来或者已经过去，所以我们只能尝试根据迄今为止我们所看到的和用户所反映的去推断。有一些人比较保守，改变对他们影响不大，还有一些人则比较激进，永远不知满足。这真的要取决于你的见解了。</p><p>点燃这一切的火花似乎就是Linux上的Steam平台，尽管在这变成现实之前我们已经看到了一些Linux游戏已经开始有重要的动作了。在任何情况下，Valve都可能是我们今天所看到的一系列复苏事件的催化剂。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Was-2014-The-Year-of-Linux-Desktop-467036-6.jpg" alt=""></p><p>在过去的十年里，Linux桌面以一种缓慢的速度在发展，并没有什么真正的改变。创新肯定是有的，但是市场份额几乎还是保持不变。无论桌面变得多么酷或Linux相比之前的任何一版多出了多少特点，很大程度上还是在原地踏步，包括那些开发商业软件的公司，他们的参与度一直很小，基本上就忽略掉了Linux。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Was-2014-The-Year-of-Linux-Desktop-467036-4.jpg" alt=""></p><p>现在，相比过去的十年里，更多的公司表现出了对Linux平台的浓厚兴趣。或许这是一种自然地演变，Valve并没有做什么，但是Linux最终还是达到了一个能被普通用户接受并理解的水平，并不只是因为令人着迷的开源技术。</p><p>驱动程序能力强了，游戏工作室就会定期移植游戏，在Linux中我们前所未见的应用和中间件就会开始出现。Linux内核发展达到了难以置信的速度，大多数发行版的安装过程通常都不怎么难，所有这一切都只是冰山一角。</p><p><img src="http://i1-news.softpedia-static.com/images/news2/Was-2014-The-Year-of-Linux-Desktop-467036-5.jpg" alt=""></p><p>所以，当有人问你2014年是不是Linux桌面年时，你可以说“是的！”，因为Linux桌面完全统治了2014年。</p><hr>',18)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),s(i,{href:"http://news.softpedia.com/news/Was-2014-The-Year-of-Linux-Desktop-467036.shtml"},{default:n(()=>[...t[0]||(t[0]=[e("http://news.softpedia.com/news/Was-2014-The-Year-of-Linux-Desktop-467036.shtml",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=e("作者：",-1)),s(i,{href:"http://news.softpedia.com/editors/browse/silviu-stahie"},{default:n(()=>[...t[2]||(t[2]=[e("Silviu Stahie",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),s(i,{href:"https://github.com/ZTinoZ"},{default:n(()=>[...t[3]||(t[3]=[e("ZTinoZ",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),s(i,{href:"https://github.com/wxy"},{default:n(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=e("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创翻译，",-1)),s(i,{href:"http://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const D=o(l,[["render",L]]);export{k as __pageData,D as default};
